"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[5718],{15179:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>d,frontMatter:()=>a,metadata:()=>r,toc:()=>l});var o=n(74848),i=n(28453);const a={slug:"Korze - Another Q Is Being Forged",title:"Korze - Another Q Is Being Forged",authors:["alexander"],hide_table_of_contents:!0,tags:["kdb/q","DefconQ","Q","Korze","Ecosystem"]},s=void 0,r={permalink:"/blog/Korze - Another Q Is Being Forged",source:"@site/blog/2026-09-14-Korze/index.md",title:"Korze - Another Q Is Being Forged",description:"If you thought the summer of new Q projects was starting to cool down, think again. Unlike the weather in the UK, the Q ecosystem certainly isn\u2019t cooling down. At least, not yet. Following my recent articles on L  and PeachQ, another project has emerged from the Q community. This time, it's Korze, a new company created by John Estrada  and a small team, with a very ambitious goal: building their own implementation of Q to give clients choice.",date:"2026-09-14T00:00:00.000Z",tags:[{label:"kdb/q",permalink:"/blog/tags/kdb-q"},{label:"DefconQ",permalink:"/blog/tags/defcon-q"},{label:"Q",permalink:"/blog/tags/q"},{label:"Korze",permalink:"/blog/tags/korze"},{label:"Ecosystem",permalink:"/blog/tags/ecosystem"}],readingTime:6.085,hasTruncateMarker:!0,authors:[{name:"Alexander Unterrainer",title:"DefconQ, KDB/Q Developer, Consultant",url:"https://github.com/AUnterrainer",imageURL:"/img/alex.jpeg",key:"alexander"}],frontMatter:{slug:"Korze - Another Q Is Being Forged",title:"Korze - Another Q Is Being Forged",authors:["alexander"],hide_table_of_contents:!0,tags:["kdb/q","DefconQ","Q","Korze","Ecosystem"]},unlisted:!1,nextItem:{title:"3 Years of DefconQ - And We Are Just Getting Started",permalink:"/blog/3 Years of DefconQ - And We Are Just Getting Started"}},h={authorsImageUrls:[void 0]},l=[{value:"Meet Korze",id:"meet-korze",level:2},{value:"John Estrada Is No Stranger to Q",id:"john-estrada-is-no-stranger-to-q",level:2},{value:"From Observation to Implementation",id:"from-observation-to-implementation",level:2},{value:"Another Q in the Ecosystem?",id:"another-q-in-the-ecosystem",level:2},{value:"The Q Ecosystem Is Getting Interesting",id:"the-q-ecosystem-is-getting-interesting",level:2},{value:"Want to See Korze in Action?",id:"want-to-see-korze-in-action",level:2},{value:"I&#39;ll Be Watching",id:"ill-be-watching",level:2}];function c(e){const t={a:"a",h2:"h2",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:["If you thought the summer of new Q projects was starting to cool down, think again. Unlike the weather in the UK, the ",(0,o.jsx)(t.strong,{children:"Q ecosystem certainly isn\u2019t cooling down. At least, not yet."})," Following my recent articles on ",(0,o.jsx)(t.a,{href:"https://www.defconq.tech/blog/L%20Has%20Landed%20-%20A%20New%20Runtime%20for%20k%20and%20q%20Enters%20the%20Scene",children:(0,o.jsx)(t.strong,{children:"L"})}),"  and ",(0,o.jsx)(t.a,{href:"https://www.defconq.tech/blog/Another%20Peach%20Falls%20Into%20the%20Basket%20-%20PeachQ",children:(0,o.jsx)(t.strong,{children:"PeachQ"})}),", another project has emerged from the Q community. This time, it's ",(0,o.jsx)(t.a,{href:"https://korze.io",children:(0,o.jsx)(t.strong,{children:"Korze"})}),", a new company created by ",(0,o.jsx)(t.a,{href:"https://www.linkedin.com/in/john-estrada-119998/",children:(0,o.jsx)(t.strong,{children:"John Estrada"})}),"  and a small team, with a very ambitious goal: building their own implementation of Q to give clients choice."]}),"\n",(0,o.jsx)(t.p,{children:"And if the name John Estrada sounds familiar, it should."}),"\n",(0,o.jsx)(t.p,{children:"John was the head of FX Trading at two large investement banks but he isn't exactly a newcomer to the Q world.  In fact, previously as a side project, he was one of the first people to document Arthur Whitney's k9 and then Shakti projects, an intriguing attempt to create another implementation of k, the cornerstone to most Q engines. Now, years later, John has decided to take on the challenge of implementation himself. And he's invited the community to have a look."}),"\n",(0,o.jsx)(t.h2,{id:"meet-korze",children:"Meet Korze"}),"\n",(0,o.jsx)(t.p,{children:"At first glance, Korze isn't simply positioning itself as \"another Q implementation\" but one that users and developers can use without changing the way they work. The company has produced a Q engine to run a tick-data system for financial application with full support for the Q language.  Compatibility isn't just syntax though, it's also as performant as required."}),"\n",(0,o.jsx)(t.p,{children:"Korze has followed an LLM-development approach, explaining why a company can deliver a Q implementation under a year.  Anyone who has worked with production market data knows that covering the average case is only one piece of the puzzle. The real engineering challenge starts when billions of messages begin arriving, markets open and close, feeds burst, storage needs to keep up, and somebody inevitably asks why yesterday's query that took 200 milliseconds now takes three seconds. Korze is being designed around those problems from the ground up. The project currently highlights custom ingestion and storage layers written in C, zero-allocation message paths, SIMD-accelerated parsing and aggregation, cache-aware layouts, and technologies such as AVX-512, NEON, io_uring, mmap and radix sorting. That is a rather different starting point from simply trying to recreate an interpreter. The question is will LLM-driven development help Korze ship new products faster? The Korze team certainly believes so, but ultimately, only time will tell."}),"\n",(0,o.jsx)(t.h2,{id:"john-estrada-is-no-stranger-to-q",children:"John Estrada Is No Stranger to Q"}),"\n",(0,o.jsx)(t.p,{children:"One of the reasons I find Korze particularly interesting is the person behind it and the approach he's taken."}),"\n",(0,o.jsx)(t.p,{children:"John has been around the Q ecosystem for a long time and has spent years working in the finance, almost entirely from the trading perspective. More importantly, he has been one of those people documenting what is happening around Q/K rather than simply watching from the sidelines."}),"\n",(0,o.jsx)(t.p,{children:"John was among the first to publicly document Shakti, Arthur Whitney's project exploring another implementation of k. That was an interesting moment in the history of the language: seeing one of the original creators of k experimenting with a new implementation naturally attracted attention from developers who had spent years working with the language."}),"\n",(0,o.jsx)(t.p,{children:"John was there documenting it. Now the tables have turned. Instead of documenting somebody else's implementation, John is working with a small team to build his own. And that makes Korze particularly worth watching."}),"\n",(0,o.jsx)(t.h2,{id:"from-observation-to-implementation",children:"From Observation to Implementation"}),"\n",(0,o.jsx)(t.p,{children:"There is something fascinating about watching an experienced practitioner move from analysing an idea to actually building it. Given the recent progress with LLM-driven development this should continue to become a common path where those on the sidelines with ideas are now able to join the development community and bring a new way of getting things done."}),"\n",(0,o.jsx)(t.p,{children:"Writing about how something could work is one thing. Building it is another."}),"\n",(0,o.jsx)(t.p,{children:"Anyone who has ever attempted to implement a programming language, database or runtime will know that the rabbit hole gets very deep, very quickly.\nLanguage semantics are only the beginning. You have parsing, evaluation, types, memory management, primitives, IPC, error handling, concurrency, I/O, storage, performance characteristics and all the weird edge cases that users have accumulated over decades of production use."}),"\n",(0,o.jsx)(t.p,{children:"And then there is the small matter of making it fast."}),"\n",(0,o.jsx)(t.p,{children:"Really fast."}),"\n",(0,o.jsx)(t.p,{children:"Korze's approach appears to be very much influenced by the environment it is targeting. The project explicitly focuses on tick-data systems where volume, velocity and cardinality all become problems simultaneously. Korze cites workloads reaching 1 TB per session per venue, 10\u2077 messages per second, and millions of symbols with microsecond-level ticks as the kind of environment it is designed to address."}),"\n",(0,o.jsx)(t.p,{children:"This is clearly not being built as an academic exercise."}),"\n",(0,o.jsx)(t.h2,{id:"another-q-in-the-ecosystem",children:"Another Q in the Ecosystem?"}),"\n",(0,o.jsxs)(t.p,{children:["At this point, you might reasonably ask: ",(0,o.jsx)(t.strong,{children:"Why do we need another Q?"})," It's a fair question, I've asked a similar question in my previous articles about L and PeachQ. My answer hasn't changed: ",(0,o.jsx)(t.strong,{children:"We don't necessarily need another Q. But we absolutely benefit from people trying to build one."})]}),"\n",(0,o.jsx)(t.p,{children:"Alternative implementations create opportunities. They allow developers to experiment with different architectural decisions. They allow ideas that may be difficult to introduce into an established implementation to be explored from scratch. They create opportunities for new tooling, new integrations and new deployment models."}),"\n",(0,o.jsx)(t.p,{children:"And perhaps most importantly, they create competition. Not necessarily commercial competition."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"Technical competition."})}),"\n",(0,o.jsx)(t.p,{children:"Someone builds something differently. Someone else asks why. Someone discovers a better approach. Someone takes that idea somewhere else. And suddenly the entire ecosystem has moved forward. That's how healthy technical communities evolve."}),"\n",(0,o.jsx)(t.h2,{id:"the-q-ecosystem-is-getting-interesting",children:"The Q Ecosystem Is Getting Interesting"}),"\n",(0,o.jsx)(t.p,{children:"If you've been following DefconQ recently, you may have noticed a bit of a pattern. First came L. Then PeachQ. Now Korze."}),"\n",(0,o.jsxs)(t.p,{children:["These projects aren't identical, and they don't necessarily have the same objectives. But they all represent something that I find incredibly encouraging: ",(0,o.jsx)(t.strong,{children:"people are investing their own time and expertise into building new things around Q."})]}),"\n",(0,o.jsx)(t.p,{children:"For a language and ecosystem that has historically been relatively small and specialised, that's significant. It means there are people thinking about what comes next. And perhaps we're only seeing the beginning."}),"\n",(0,o.jsx)(t.h2,{id:"want-to-see-korze-in-action",children:"Want to See Korze in Action?"}),"\n",(0,o.jsxs)(t.p,{children:["The best part is that you don't have to take my word for it. John has kindly agreed to showcase ",(0,o.jsx)(t.strong,{children:"Korze in a dedicated demo for the DefconQ community."})," We'll get a chance to see what the team has been building, understand the thinking behind the project, and, most importantly, ask questions directly to the person building it."]}),"\n",(0,o.jsx)(t.p,{children:"If you're interested in KDB, Q, market-data infrastructure, databases, runtimes or simply curious about where this growing ecosystem is heading, this is one I'd recommend joining."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"John is opening the door and giving us a look under the hood."})}),"\n",(0,o.jsx)(t.p,{children:"You can sign up for the DefconQ Korze demo and see the project for yourself. Feel free to reach out."}),"\n",(0,o.jsx)(t.h2,{id:"ill-be-watching",children:"I'll Be Watching"}),"\n",(0,o.jsx)(t.p,{children:"Korze is still very much a project in development, and that's exactly what makes it interesting. We're watching an experienced Q practitioner take everything he has learned from years in the ecosystem and apply it to building something from the ground up."}),"\n",(0,o.jsx)(t.p,{children:"Where it goes remains to be seen."}),"\n",(0,o.jsx)(t.p,{children:"But one thing is becoming increasingly difficult to ignore:"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"The Q ecosystem is moving."})}),"\n",(0,o.jsx)(t.p,{children:"And I'm certainly not going to stop watching."}),"\n",(0,o.jsx)(t.p,{children:"Stay tuned."})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var o=n(96540);const i={},a=o.createContext(i);function s(e){const t=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);